// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readyz", wrapper.GetReadiness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/hits", wrapper.ListPointStorms)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/live/storms", wrapper.GetLiveSnapshot)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/live/stream", wrapper.StreamLiveEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/meta", wrapper.GetMeta)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/openapi.json", wrapper.GetOpenApiDocument)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/places/nearest", wrapper.GetNearestPlace)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/places/search", wrapper.SearchPlaces)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/places/{placeId}", wrapper.GetPlace)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/places/{placeId}/storms", wrapper.ListPlaceStorms)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/storms", wrapper.ListStorms)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/storms/{sid}", wrapper.GetStorm)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/storms/{sid}/places", wrapper.ListStormPlaces)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/storms/{sid}/track", wrapper.GetStormTrack)

	return m
}
